<?php
define('APP_INIT', true); $pageTitle='SaaS Platform Administration'; $activeMenu='platform';
require_once __DIR__ . '/../../includes/header.php'; require_once ROOT_PATH . '/includes/platform_check.php'; requirePlatformAdmin();
$db=Database::getConnection();
$tenants=$db->query("SELECT t.*, sp.name AS plan_name, ts.status AS subscription_status, ts.ends_at FROM tenants t LEFT JOIN tenant_subscriptions ts ON ts.id=(SELECT s2.id FROM tenant_subscriptions s2 WHERE s2.tenant_id=t.id ORDER BY s2.id DESC LIMIT 1) LEFT JOIN subscription_plans sp ON sp.id=ts.plan_id ORDER BY t.id DESC")->fetchAll();
$plans=$db->query("SELECT * FROM subscription_plans WHERE status='active' ORDER BY id")->fetchAll();
$pendingPayments=$db->query("SELECT p.*,t.name tenant_name FROM subscription_payments p JOIN tenants t ON t.id=p.tenant_id WHERE p.status='pending' ORDER BY p.id DESC LIMIT 10")->fetchAll();
?>
<div class="page-header-container"><div><h2 class="page-title">SaaS Platform Admin</h2><div class="page-subtitle">Manage independent dealership tenants, plans and subscription access.</div></div><button class="btn btn-primary-custom" data-bs-toggle="modal" data-bs-target="#tenantModal"><i class="fa-solid fa-plus me-1"></i>Add Tenant</button></div>
<div class="row g-3 mb-4"><div class="col-md-4"><div class="dark-card py-3"><small class="text-secondary text-uppercase">Total tenants</small><div class="fs-3 fw-bold"><?=count($tenants)?></div></div></div><div class="col-md-4"><div class="dark-card py-3"><small class="text-secondary text-uppercase">Active subscriptions</small><div class="fs-3 fw-bold text-success"><?=count(array_filter($tenants,fn($t)=>in_array($t['subscription_status'],['active','trial','grace_period'],true)))?></div></div></div><div class="col-md-4"><div class="dark-card py-3"><small class="text-secondary text-uppercase">Pending payment reviews</small><div class="fs-3 fw-bold text-warning"><?=(int)$db->query("SELECT COUNT(*) FROM subscription_payments WHERE status='pending'")->fetchColumn()?></div></div></div></div>
<div class="dark-card"><div class="card-header-clean"><div class="card-title-clean"><i class="fa-solid fa-building-shield text-primary-light"></i><span>Dealership tenants</span></div></div><div class="table-responsive"><table class="dark-table"><thead><tr><th>Tenant</th><th>Owner</th><th>Plan</th><th>Subscription</th><th>Ends</th><th>Status</th><th>Access</th></tr></thead><tbody><?php foreach($tenants as $t):?><tr><td><strong><?=htmlspecialchars($t['name'])?></strong><br><small class="text-secondary"><?=htmlspecialchars($t['slug'])?></small></td><td><?=htmlspecialchars($t['owner_name']?:'—')?><br><small><?=htmlspecialchars($t['owner_phone']?:'')?></small></td><td><?=htmlspecialchars($t['plan_name']?:'Unassigned')?></td><td><?=htmlspecialchars($t['subscription_status']?:'None')?></td><td><?=htmlspecialchars($t['ends_at']?:'—')?></td><td><span class="badge-custom badge-primary"><?=htmlspecialchars($t['status'])?></span></td><td><button class="btn btn-sm btn-outline-light" onclick="changeSubscription(<?=$t['id']?>)">Manage</button></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="dark-card mt-4"><div class="card-header-clean"><div class="card-title-clean"><i class="fa-solid fa-layer-group text-primary-light"></i><span>Subscription plans</span></div><button class="btn btn-sm btn-primary" data-bs-toggle="modal" data-bs-target="#planModal">Add plan</button></div><div class="table-responsive"><table class="dark-table"><thead><tr><th>Code</th><th>Plan</th><th>Price</th><th>Limits: company / product / customer / user</th><th>Period</th></tr></thead><tbody><?php foreach($plans as $p):?><tr><td><?=htmlspecialchars($p['code'])?></td><td><?=htmlspecialchars($p['name'])?></td><td><?=formatBDT($p['price'])?></td><td><?=($p['company_limit']??'∞').' / '.($p['product_limit']??'∞').' / '.($p['customer_limit']??'∞').' / '.($p['user_limit']??'∞')?></td><td><?=htmlspecialchars($p['billing_period'])?></td></tr><?php endforeach?></tbody></table></div></div>
<div class="dark-card mt-4"><div class="card-header-clean"><div class="card-title-clean"><i class="fa-solid fa-money-check-dollar text-primary-light"></i><span>Pending manual payments</span></div></div><div class="table-responsive"><table class="dark-table"><thead><tr><th>Tenant</th><th>Method</th><th>Reference</th><th>Amount</th><th>Action</th></tr></thead><tbody><?php foreach($pendingPayments as $p):?><tr><td><?=htmlspecialchars($p['tenant_name'])?></td><td><?=htmlspecialchars($p['payment_method'])?></td><td><?=htmlspecialchars($p['transaction_reference']??'—')?></td><td><?=formatBDT($p['amount'])?></td><td><button class="btn btn-sm btn-success" onclick="reviewPayment(<?=$p['id']?>,'approved')">Approve</button> <button class="btn btn-sm btn-danger" onclick="reviewPayment(<?=$p['id']?>,'rejected')">Reject</button></td></tr><?php endforeach?></tbody></table></div></div>
<div class="modal fade" id="tenantModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content bg-dark text-white"><form id="tenantForm"><div class="modal-header"><h5 class="modal-title">Create tenant</h5><button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal"></button></div><div class="modal-body"><?php echo csrfField();?><div class="mb-2"><label>Business name</label><input name="name" required class="form-control"></div><div class="mb-2"><label>Owner name</label><input name="owner_name" required class="form-control"></div><div class="mb-2"><label>Owner phone</label><input name="owner_phone" class="form-control"></div><div class="mb-2"><label>Plan</label><select name="plan_id" class="form-select"><?php foreach($plans as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach?></select></div><div class="mb-2"><label>Initial admin username</label><input name="username" required class="form-control"></div><div class="mb-2"><label>Initial admin password</label><input type="password" name="password" required minlength="8" class="form-control"></div></div><div class="modal-footer"><button class="btn btn-primary">Create tenant</button></div></form></div></div></div>
<div class="modal fade" id="planModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content bg-dark text-white"><form id="planForm"><div class="modal-header"><h5 class="modal-title">Subscription plan</h5><button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal"></button></div><div class="modal-body"><?php echo csrfField();?><div class="row g-2"><div class="col-6"><label>Code</label><input name="code" required class="form-control"></div><div class="col-6"><label>Name</label><input name="name" required class="form-control"></div><div class="col-6"><label>Price</label><input name="price" type="number" min="0" step=".01" value="0" class="form-control"></div><div class="col-6"><label>Period</label><select name="billing_period" class="form-select"><option>monthly</option><option>yearly</option><option>custom</option></select></div><?php foreach(['company','product','customer','user'] as $limit):?><div class="col-6"><label><?=$limit?> limit (blank = unlimited)</label><input name="<?=$limit?>_limit" type="number" min="0" class="form-control"></div><?php endforeach?></div></div><div class="modal-footer"><button class="btn btn-primary">Save plan</button></div></form></div></div></div>
<script>async function submitForm(id,url){const f=document.getElementById(id),r=await fetch(`${BASE_URL}${url}`,{method:'POST',body:new FormData(f),headers:{'X-Requested-With':'XMLHttpRequest'}}),j=await r.json();if(j.success)location.reload();else alert(j.message)}document.getElementById('tenantForm').onsubmit=e=>{e.preventDefault();submitForm('tenantForm','/ajax/platform/create_tenant.php')};document.getElementById('planForm').onsubmit=e=>{e.preventDefault();submitForm('planForm','/ajax/platform/save_plan.php')};async function changeSubscription(id){const plan=prompt('Plan ID (1 Basic, 2 Standard, 3 Premium):','3'),status=prompt('Status: trial, active, grace_period, expired, suspended, cancelled','active');if(!plan||!status)return;const f=new FormData();f.append('tenant_id',id);f.append('plan_id',plan);f.append('status',status);f.append('csrf_token',document.querySelector('[name=csrf_token]').value);const r=await fetch(`${BASE_URL}/ajax/platform/update_subscription.php`,{method:'POST',body:f}),j=await r.json();if(j.success)location.reload();else alert(j.message)}async function reviewPayment(id,status){const f=new FormData();f.append('id',id);f.append('status',status);f.append('csrf_token',document.querySelector('[name=csrf_token]').value);const r=await fetch(`${BASE_URL}/ajax/platform/review_payment.php`,{method:'POST',body:f}),j=await r.json();if(j.success)location.reload();else alert(j.message)}</script>
